28	// ── Create ────────────────────────────────────────────────────────────────────
29	
30	export async function createFlashEventAction(
31	  formData: FormData
32	): Promise<ActionResult & { id?: string }> {
33	  const auth = await getAuthenticatedUser()
34	  if (!auth) return { success: false, error: 'Not authenticated' }
35	  if (!['owner', 'admin', 'receptionist'].includes(auth.role)) {
36	    return { success: false, error: 'Insufficient permissions' }
37	  }
38	
39	  const artistIdRaw = formData.get('artistId')
40	  const locationIdRaw = formData.get('locationId')
41	  const artistId =
42	    typeof artistIdRaw === 'string' && artistIdRaw !== '__none__' && artistIdRaw !== ''
43	      ? artistIdRaw
44	      : undefined
45	  const locationId =
46	    typeof locationIdRaw === 'string' && locationIdRaw !== '__none__' && locationIdRaw !== ''
47	      ? locationIdRaw
48	      : undefined
49	
50	  const raw = {
51	    title: formData.get('title'),
52	    slug: formData.get('slug') || undefined,
53	    description: formData.get('description') || undefined,
54	    eventDate: formData.get('eventDate'),
55	    startTime: formData.get('startTime'),
56	    endTime: formData.get('endTime'),
57	    slotDurationMin: Number(formData.get('slotDurationMin')),
58	    slotPriceCents: Number(formData.get('slotPriceCents') ?? 0),
59	    depositCents: Number(formData.get('depositCents') ?? 0),
60	    currency: formData.get('currency') || 'USD',
61	    maxSlots: formData.get('maxSlots') ? Number(formData.get('maxSlots')) : undefined,
62	    coverImageUrl: formData.get('coverImageUrl') || undefined,
63	    flyerUrl: formData.get('flyerUrl') || undefined,
64	    locationId,
65	    artistId,
66	    public: formData.get('public') !== 'false',
67	  }
68	
69	  const parsed = flashEventCreateSchema.safeParse(raw)
70	  if (!parsed.success) {
71	    return { success: false, error: parsed.error.errors[0]?.message ?? 'Validation failed' }
72	  }
73	
74	  try {
75	    const event = await createFlashEvent(auth.studioId, parsed.data)
76	    revalidatePath('/flash-events')
77	    return { success: true, id: event.id }
78	  } catch (err) {
79	    logger.error({ err }, 'createFlashEventAction failed')
80	    const message = err instanceof Error ? err.message : 'Failed to create event'
81	    return { success: false, error: message }
82	  }
83	}
