85	// ── Update ────────────────────────────────────────────────────────────────────
86	
87	export async function updateFlashEventAction(
88	  eventId: string,
89	  formData: FormData
90	): Promise<ActionResult> {
91	  const auth = await getAuthenticatedUser()
92	  if (!auth) return { success: false, error: 'Not authenticated' }
93	  if (!['owner', 'admin', 'receptionist'].includes(auth.role)) {
94	    return { success: false, error: 'Insufficient permissions' }
95	  }
96	
97	  const raw: Record<string, unknown> = {}
98	  const title = formData.get('title')
99	  if (title) raw.title = title
100	  const slug = formData.get('slug')
101	  if (slug) raw.slug = slug
102	  const description = formData.get('description')
103	  if (description !== null) raw.description = description || null
104	  const eventDate = formData.get('eventDate')
105	  if (eventDate) raw.eventDate = eventDate
106	  const startTime = formData.get('startTime')
107	  if (startTime) raw.startTime = startTime
108	  const endTime = formData.get('endTime')
109	  if (endTime) raw.endTime = endTime
110	  const slotDurationMin = formData.get('slotDurationMin')
111	  if (slotDurationMin) raw.slotDurationMin = Number(slotDurationMin)
112	  const slotPriceCents = formData.get('slotPriceCents')
113	  if (slotPriceCents !== null) raw.slotPriceCents = Number(slotPriceCents)
114	  const depositCents = formData.get('depositCents')
115	  if (depositCents !== null) raw.depositCents = Number(depositCents)
116	  const maxSlots = formData.get('maxSlots')
117	  if (maxSlots !== null) raw.maxSlots = maxSlots ? Number(maxSlots) : null
118	  const coverImageUrl = formData.get('coverImageUrl')
119	  if (coverImageUrl !== null) raw.coverImageUrl = coverImageUrl || null
120	  const flyerUrl = formData.get('flyerUrl')
121	  if (flyerUrl !== null) raw.flyerUrl = flyerUrl || null
122	  const locationId = formData.get('locationId')
123	  if (locationId !== null) {
124	    raw.locationId =
125	      typeof locationId === 'string' && locationId !== '__none__' && locationId !== ''
126	        ? locationId
127	        : null
128	  }
129	  const artistId = formData.get('artistId')
130	  if (artistId !== null) {
131	    raw.artistId =
132	      typeof artistId === 'string' && artistId !== '__none__' && artistId !== ''
133	        ? artistId
134	        : null
135	  }
136	  const isPublic = formData.get('public')
137	  if (isPublic !== null) raw.public = isPublic !== 'false'
138	
139	  const parsed = flashEventUpdateSchema.safeParse(raw)
140	  if (!parsed.success) {
141	    return { success: false, error: parsed.error.errors[0]?.message ?? 'Validation failed' }
142	  }
143	
144	  try {
145	    await updateFlashEvent(auth.studioId, eventId, parsed.data)
146	    revalidatePath(`/flash-events/${eventId}`)
147	    revalidatePath('/flash-events')
148	    return { success: true }
149	  } catch (err) {
150	    logger.error({ err, eventId }, 'updateFlashEventAction failed')
151	    const message = err instanceof Error ? err.message : 'Failed to update event'
152	    return { success: false, error: message }
153	  }
154	}
