329	import { z } from 'zod'
330	
331	const walkInSchema = z.object({
332	  firstName: z.string().min(1).max(80),
333	  lastName: z.string().max(80).optional().nullable(),
334	  email: z.string().email(),
335	  phone: z.string().max(40).optional().nullable(),
336	  notes: z.string().max(500).optional().nullable(),
337	  designId: z.string().uuid().optional().nullable(),
338	  chargeAtDesk: z.boolean(),
339	})
340	
341	type WalkInRpcResult = {
342	  booking_id?: string
343	  booking_token?: string
344	  slot_id?: string
345	  error?: string
346	} | null
347	
348	export async function markSlotWalkInAction(
349	  eventId: string,
350	  slotId: string,
351	  formData: FormData
352	): Promise<ActionResult & { bookingId?: string }> {
353	  const auth = await getAuthenticatedUser()
354	  if (!auth) return { success: false, error: 'Not authenticated' }
355	  if (!['owner', 'admin', 'receptionist'].includes(auth.role)) {
356	    return { success: false, error: 'Insufficient permissions' }
357	  }
358	
359	  const raw = {
360	    firstName: formData.get('firstName'),
361	    lastName: formData.get('lastName') || null,
362	    email: formData.get('email'),
363	    phone: formData.get('phone') || null,
364	    notes: formData.get('notes') || null,
365	    designId: (() => {
366	      const v = formData.get('designId')
367	      return typeof v === 'string' && v !== '__none__' && v !== '' ? v : null
368	    })(),
369	    chargeAtDesk: formData.get('chargeAtDesk') !== 'false',
370	  }
371	
372	  const parsed = walkInSchema.safeParse(raw)
373	  if (!parsed.success) {
374	    return { success: false, error: parsed.error.errors[0]?.message ?? 'Validation failed' }
375	  }
376	
377	  try {
378	    const { createServiceRoleClient } = await import('@/lib/supabase/server')
379	    const supabase = createServiceRoleClient()
380	
381	    const rpc = supabase.rpc as unknown as (
382	      fn: 'mark_flash_slot_walkin',
383	      args: { p_slot_id: string; p_client_info: Record<string, unknown>; p_charge_at_desk: boolean }
384	    ) => Promise<{ data: WalkInRpcResult; error: { message: string } | null }>
385	
386	    const { data, error } = await rpc('mark_flash_slot_walkin', {
387	      p_slot_id: slotId,
388	      p_client_info: {
389	        first_name: parsed.data.firstName,
390	        last_name: parsed.data.lastName,
391	        email: parsed.data.email,
392	        phone: parsed.data.phone,
393	        notes: parsed.data.notes,
394	        design_id: parsed.data.designId,
395	      },
396	      p_charge_at_desk: parsed.data.chargeAtDesk,
397	    })
398	
399	    if (error) {
400	      logger.error({ error, eventId, slotId }, 'markSlotWalkInAction RPC failed')
401	      return { success: false, error: error.message }
402	    }
403	
404	    const result = data
405	    if (result?.error) {
406	      return { success: false, error: result.error }
407	    }
408	
409	    const { logAuditAction } = await import('@/lib/audit')
410	    await logAuditAction(
411	      auth.user.id,
412	      'flash_event.slot.walk_in',
413	      { type: 'flash_event_slot', id: slotId },
414	      { eventId, bookingId: result?.booking_id, chargeAtDesk: parsed.data.chargeAtDesk },
415	      auth.studioId
416	    )
417	
418	    revalidatePath(`/flash-events/${eventId}`)
419	    const bookingId = result?.booking_id
420	    return bookingId ? { success: true, bookingId } : { success: true }
421	  } catch (err) {
422	    logger.error({ err, eventId, slotId }, 'markSlotWalkInAction failed')
423	    const message = err instanceof Error ? err.message : 'Failed to mark walk-in'
424	    return { success: false, error: message }
425	  }
426	}
