530	// ── Send reminder (deposit link / SMS) ───────────────────────────────────────
531	
532	export async function sendSlotReminderAction(
533	  eventId: string,
534	  slotId: string
535	): Promise<ActionResult> {
536	  const auth = await getAuthenticatedUser()
537	  if (!auth) return { success: false, error: 'Not authenticated' }
538	  if (!['owner', 'admin', 'receptionist'].includes(auth.role)) {
539	    return { success: false, error: 'Insufficient permissions' }
540	  }
541	
542	  try {
543	    const { createClient } = await import('@/lib/supabase/server')
544	    const supabase = await createClient()
545	
546	    // Fetch slot + linked booking + client email
547	    const { data: slotRow, error: fetchErr } = await supabase
548	      .from('flash_event_slots')
549	      .select('id, status, booking_id')
550	      .eq('id', slotId)
551	      .single()
552	
553	    if (fetchErr || !slotRow) {
554	      return { success: false, error: 'Slot not found' }
555	    }
556	
557	    let clientEmail: string | null = null
558	    let clientId: string | null = null
559	
560	    if (slotRow.booking_id) {
561	      const { data: bookingRow } = await supabase
562	        .from('bookings')
563	        .select('client_id, clients(id, email)')
564	        .eq('id', slotRow.booking_id)
565	        .single()
566	
567	      const rawClient = bookingRow?.clients
568	      const client = Array.isArray(rawClient) ? rawClient[0] : rawClient
569	      clientEmail = (client as { email: string | null } | undefined)?.email ?? null
570	      clientId = (client as { id: string } | undefined)?.id ?? null
571	    }
572	
573	    if (!clientEmail) {
574	      // No contact info — log and return success (best-effort, non-blocking)
575	      logger.info({ eventId, slotId }, 'sendSlotReminderAction: no client email on slot — skipping queue')
576	      return { success: true }
577	    }
578	
579	    // TODO: enqueueSendDepositLink requires `project_id` (a tattoo project concept).
580	    // Flash events have no project_id. When the queue contract is extended to support
581	    // flash_event context (e.g. flash_booking_id), replace the send-email stub below with:
582	    //   await enqueueSendDepositLink({
583	    //     project_id: '<flash_booking_id or eventId bridge>',
584	    //     client_id: clientId,
585	    //     checkout_url: '<dodo checkout url from booking>',
586	    //     amount_cents: depositCents,
587	    //     channel: clientPhone ? 'sms' : 'email',
588	    //   })
589	    const { enqueueJob } = await import('@/lib/queue')
590	    await enqueueJob('send-email', {
591	      to: clientEmail,
592	      template: 'flash_slot_reminder',
